                  onClick={() => setUnread(false)}
                  size="sm"
                  type="button"
                  variant="ghost"
                >
                  Mark all as read
                </Button>
              </div>
            </PopoverContent>
          </Popover>
          <DropdownMenu>
            <DropdownMenuTrigger
              render={
                <Button
                  aria-label="Account menu"
                  className="gap-2 rounded-full pr-2.5 pl-1"
                  size="lg"
                  variant="outline"
                />
              }
            >
              <Avatar className="size-7">
                <AvatarFallback className="bg-linear-to-br from-amber-400 to-red-500 font-semibold text-[0.6875rem] text-white">
                  EB
                </AvatarFallback>
              </Avatar>
              <ChevronDown data-icon="inline-end" />
            </DropdownMenuTrigger>
            <DropdownMenuContent
              align="end"
              className="w-60 rounded-[10px] p-1.5"
            >
              <DropdownMenuGroup>
                <DropdownMenuLabel className="flex flex-col gap-0.5 px-2.5 py-2">
                  <div className="font-medium text-foreground text-sm">
                    Ephraim Brooks
                  </div>
                  <div className="font-normal text-[0.8125rem]">
                    ephraim@lumenlabs.io
                  </div>
                </DropdownMenuLabel>
              </DropdownMenuGroup>
              <DropdownMenuSeparator />
              <DropdownMenuGroup>
                <DropdownMenuItem
                  className="min-h-8.5 gap-2.5 px-2.5"
                  render={
                    <a aria-label="Profile" href="/settings/profile">
                      <UserRound />
                      Profile
                    </a>
                  }
                />
                <DropdownMenuItem
                  className="min-h-8.5 gap-2.5 px-2.5"
                  render={
                    <a
                      aria-label="Notifications"
                      href="/settings/notifications"
                    >
                      <Bell />
                      Notifications
                    </a>
                  }
                />
                <DropdownMenuItem
                  className="min-h-8.5 gap-2.5 px-2.5"
                  render={
                    <a aria-label="Security" href="/settings/security">
                      <LockKeyhole />
                      Security
                    </a>
                  }
                />
              </DropdownMenuGroup>
              <DropdownMenuSeparator />
              <DropdownMenuGroup>
                <DropdownMenuItem
                  className="min-h-8.5 gap-2.5 px-2.5"
                  render={
                    <a aria-label="Log out" href="/login">
                      <LogOut />
                      Log out
                    </a>
                  }
                  variant="destructive"
                />
              </DropdownMenuGroup>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </header>
      <Dialog
        onOpenChange={(open) => {
          if (!open) {
            setCustomRange(null);
          }
        }}
        open={customRange !== null}
      >
        <DialogContent>
          {customRange && (
            <form
              className="flex flex-col gap-5"
              onSubmit={(event) => {
                event.preventDefault();
                if (
                  customRange.from &&
                  customRange.to &&
                  customRange.from <= customRange.to
                ) {
                  onRangeChange(customRange);
                  setCustomRange(null);
                }
              }}
            >
              <DialogHeader>
                <DialogTitle>Custom date range</DialogTitle>
                <DialogDescription>
                  Choose the dates to include in your charts.
                </DialogDescription>
              </DialogHeader>
              <FieldGroup>
                <Field>
                  <FieldLabel htmlFor="dashboard-from">Start date</FieldLabel>
                  <Input
                    id="dashboard-from"
                    max={customRange.to}
                    name="from"
                    onChange={(event) =>
                      setCustomRange({
                        ...customRange,
                        from: event.target.value,
                      })
                    }
                    required
                    type="date"
                    value={customRange.from}
                  />
                </Field>
                <Field>
                  <FieldLabel htmlFor="dashboard-to">End date</FieldLabel>
                  <Input
                    id="dashboard-to"
                    min={customRange.from}
                    name="to"
                    onChange={(event) =>
                      setCustomRange({ ...customRange, to: event.target.value })
                    }
                    required
                    type="date"
                    value={customRange.to}
                  />
                </Field>
              </FieldGroup>
              <DialogFooter>
                <Button
                  onClick={() => setCustomRange(null)}
                  type="button"
                  variant="outline"
                >
                  Cancel
                </Button>
                <Button type="submit">Apply range</Button>
              </DialogFooter>
            </form>
          )}
        </DialogContent>
      </Dialog>
    </>
  );
}

